using Path=std::filesystem::path;namespace ev=reader::epubviews;
void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
template<class F>void rejects(F f,const char* why){bool bad=false;try{f();}catch(...){bad=true;}check(bad,why);}
QByteArray read(const Path& p){return underlay::readBounded(p,64*1024*1024);}
QString hash(const QByteArray& b){return QString::fromLatin1(underlay::digest(b).toHex());}
void word16(QByteArray& out,unsigned v){out.append(char(v));out.append(char(v>>8));}
void word32(QByteArray& out,std::uint32_t v){word16(out,v&65535);word16(out,v>>16);}
std::uint32_t crc(const QByteArray& bytes){std::uint32_t value=~0u;for(auto byte:bytes){value^=static_cast<unsigned char>(byte);for(int n=0;n<8;++n)value=(value>>1)^(0xedb88320u&std::uint32_t(-int(value&1)));}return ~value;}
QByteArray zip(const std::vector<std::pair<QByteArray,QByteArray>>& entries){QByteArray out,central;for(auto& [name,data]:entries){auto offset=out.size(),size=data.size();auto sum=crc(data);word32(out,0x04034b50);for(unsigned n:{20,0,0,0,0})word16(out,n);word32(out,sum);word32(out,size);word32(out,size);word16(out,name.size());word16(out,0);out+=name;out+=data;word32(central,0x02014b50);for(unsigned n:{20,20,0,0,0,0})word16(central,n);word32(central,sum);word32(central,size);word32(central,size);word16(central,name.size());for(int n=0;n<4;++n)word16(central,0);word32(central,0);word32(central,offset);central+=name;}auto offset=out.size();out+=central;word32(out,0x06054b50);word16(out,0);word16(out,0);word16(out,entries.size());word16(out,entries.size());word32(out,central.size());word32(out,offset);word16(out,0);return out;}
library::Document import(const Path& libraryRoot,const Path& source){library::Store store(libraryRoot);return store.importDocument(source,"Authored EPUB helper fixture",[](const Path& p,const QString&){auto sha=hash(read(p));epub::ReflowDocument doc(p,"12345678-1234-1234-1234-123456789abc",sha);return library::Inspection{doc.pageCount(),"mupdf-1.28.3-epub-v1-w600-h800-em12",{}};});}
int main(int argc,char** argv){QCoreApplication application(argc,argv);try{check(argc==2,"usage source-root");Path sourceRoot=argv[1];QTemporaryDir temporary;check(temporary.isValid(),"test directory");Path base=temporary.path().toStdString();auto root=base/"library";auto book=import(root,sourceRoot/"fixtures/library/authored-three-chapters.epub");auto docroot=library::documentRoot(root,book.id);auto descriptor=read(docroot/"document.json"),source=read(library::sourcePath(docroot,library::descriptor(docroot)));auto baseSet=ev::readSet(docroot,{});auto baseline=reader::prepareEpubView(sourceRoot,docroot,1,baseSet);auto basePath=ev::storagePath(docroot,baseSet,1);auto exact=underlay::prepare(sourceRoot,basePath,1,true,docroot);check(baseline.metadata==exact.metadata&&baseline.background==exact.background&&baseline.ink==exact.ink,"baseline delegate exact bytes");auto baseJournal=read(basePath/"annotations.ink");
 auto staged=reader::stageEpubView(sourceRoot,docroot,{},epub::Layout{200,160,24},1);check(!staged.viewId.isEmpty()&&staged.targetPage>1&&staged.readingAnchor["kind"]=="reading-position"&&ev::activeSet(docroot).id.isEmpty(),"source anchored staging without activation");auto set=ev::readSet(docroot,staged.viewId);auto prepared=reader::prepareEpubView(sourceRoot,docroot,staged.targetPage,set);check(prepared.metadata["schema"]==4&&prepared.metadata["view_receipt"]==set.receipt&&prepared.metadata["layout"]==set.receipt["layout_id"]&&prepared.metadata["pages"]==set.receipt["pages"],"schema4 actual receipt binding");check(prepared.text&&prepared.text->available(),"same layout semantic text available");epub::ReflowDocument actual(library::sourcePath(docroot,library::descriptor(docroot)),book.id,book.sha256,{200,160,24});auto geometry=actual.page(staged.targetPage),resolved=actual.resolve(staged.readingAnchor);check(resolved["status"]=="resolved"&&resolved["page"]==staged.targetPage&&prepared.text->data["text"]==geometry["text"]&&prepared.text->data["chars"]==geometry["chars"]&&prepared.text->data["lines"]==geometry["lines"]&&prepared.text->data["blocks"]==geometry["blocks"],"text and raster use exact same reflow page");auto startCaptured=actual.captureSpineStart(0);check(startCaptured["status"]=="anchored","small layout textless first page captures source start");epub::ReflowDocument baselineActual(library::sourcePath(docroot,library::descriptor(docroot)),book.id,book.sha256);auto startResolved=baselineActual.resolve(startCaptured["anchor"].toObject());check(!baselineActual.page(0)["text"].toString().trimmed().isEmpty()&&startResolved["status"]=="resolved"&&startResolved["page"]==0,"spine-start resolves actual chapter start even with target text");check(baselineActual.captureSpineStart(0)["status"]=="unresolved","textful origin cannot capture spine-start");auto raster=actual.renderPage(staged.targetPage);for(int y=120;y<1900;++y)for(int x=0;x<1620;++x)check(prepared.background[y*underlay::Stride+x]==raster.rgb32[y*raster.stride+x],"semantic helper uses actual reflow raster");auto path=ev::storagePath(docroot,set,staged.targetPage);auto cache=underlay::loadPrepared(path/"prepared.bin");check(cache.metadata==prepared.metadata&&cache.background==prepared.background&&cache.ink==prepared.ink,"cache round trip");auto loaded=semantic::loadGeometry(path/"semantic-text.json",prepared.binding,book.id);check(loaded&&loaded->data==prepared.text->data,"semantic sidecar exact view path");
 for(int variant=0;variant<3;++variant){auto forged=prepared;if(variant==0){auto receipt=forged.metadata["view_receipt"].toObject();receipt["pages"]=receipt["pages"].toInt()+1;forged.metadata["view_receipt"]=receipt;}else if(variant==1)forged.metadata["layout"]="epub-reflow-v1:"+QString(64,'0');else{auto transform=forged.metadata["pageToSurface"].toArray();transform[4]=transform[4].toDouble()+1;forged.metadata["pageToSurface"]=transform;}rejects([&]{underlay::savePrepared(base/"forged.bin",forged);},"forged receipt layout or transform rejected");check(!std::filesystem::exists(base/"forged.bin"),"rejected forged cache not written");}
 auto restored=reader::stageEpubView(sourceRoot,docroot,set.id,epub::Layout{},staged.targetPage);check(restored.viewId.isEmpty()&&restored.targetPage==1,"baseline restoration resolves source word not new page index");auto bad=set;bad.receipt["pages"]=1;rejects([&]{reader::prepareEpubView(sourceRoot,docroot,0,bad);},"caller receipt mismatch refused");rejects([&]{reader::prepareEpubView(sourceRoot,docroot,set.receipt["pages"].toInt(),set);},"invalid page refused");rejects([&]{reader::stageEpubView(sourceRoot,docroot,{},epub::Layout{100,100,6},1);},"unrenderable fit refused before staging");
 {underlay::Journal journal(path/"annotations.ink",prepared.binding);underlay::Operation op;op.id=1;op.count=2;op.points[0]={300,500,spike::Phase::Down};op.points[1]={330,500,spike::Phase::Up};journal.append(op);}auto replay=reader::prepareEpubView(sourceRoot,docroot,staged.targetPage,set);check(replay.lastId==1&&replay.ink[500*underlay::Stride+315]==0xff000000u,"view journal replay retained");check(read(basePath/"annotations.ink")==baseJournal&&read(docroot/"document.json")==descriptor&&read(library::sourcePath(docroot,library::descriptor(docroot)))==source,"base journal descriptor source preserved");
 auto cover=zip({{"mimetype","application/epub+zip"},{"META-INF/container.xml","<container xmlns=\"urn:oasis:names:tc:opendocument:xmlns:container\"><rootfiles><rootfile full-path=\"EPUB/content.opf\" media-type=\"application/oebps-package+xml\"/></rootfiles></container>"},{"EPUB/content.opf","<package xmlns=\"http://www.idpf.org/2007/opf\" version=\"2.0\" unique-identifier=\"book\"><metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"><dc:identifier id=\"book\">cover-test</dc:identifier><dc:title>Cover</dc:title><dc:language>en</dc:language></metadata><manifest><item id=\"c1\" href=\"cover.xhtml\" media-type=\"application/xhtml+xml\"/><item id=\"c2\" href=\"second.xhtml\" media-type=\"application/xhtml+xml\"/><item id=\"image\" href=\"image.png\" media-type=\"image/png\"/></manifest><spine><itemref idref=\"c1\"/><itemref idref=\"c2\"/></spine></package>"},{"EPUB/cover.xhtml","<html xmlns=\"http://www.w3.org/1999/xhtml\"><head><title>Cover</title></head><body><img src=\"image.png\"/></body></html>"},{"EPUB/second.xhtml","<html xmlns=\"http://www.w3.org/1999/xhtml\"><head><title>Second</title></head><body><img src=\"image.png\"/></body></html>"},{"EPUB/image.png",read(sourceRoot/"fixtures/library/marker.png")}});auto coverFile=base/"cover.epub";underlay::atomicFile(coverFile,cover);auto coverBook=import(base/"covers",coverFile);auto coverRoot=library::documentRoot(base/"covers",coverBook.id);auto coverStage=reader::stageEpubView(sourceRoot,coverRoot,{},epub::Layout{600,800,18},0);check(coverStage.targetPage==0&&coverStage.readingAnchor["kind"]=="spine-start","textless cover uses verified spine start");auto coverPrepared=reader::prepareEpubView(sourceRoot,coverRoot,0,ev::readSet(coverRoot,coverStage.viewId));check(coverPrepared.text&&coverPrepared.text->data["status"]=="NO TEXT LAYER","textless cover no fabricated text");{auto second=reader::stageEpubView(sourceRoot,coverRoot,{},epub::Layout{600,800,24},1);epub::ReflowDocument staged(coverFile,coverBook.id,coverBook.sha256,{600,800,24});check(second.readingAnchor.isEmpty()&&second.targetPage>=0&&second.targetPage<staged.pageCount()&&staged.chapterFraction(second.targetPage).chapter==1,"nonfirst textless page keeps its chapter (no fabricated anchor) instead of refusing the layout");}auto coverAnchor=coverStage.readingAnchor;coverAnchor["chapterSourceSha256"]=QString(64,'0');epub::ReflowDocument coverDoc(coverFile,coverBook.id,coverBook.sha256,{600,800,18});check(coverDoc.resolve(coverAnchor)["status"]=="unresolved","spine start chapter hash required");std::cout<<"PREPARE_EPUB_VIEW_PASS physical=NOT_RUN\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
